        if(!$accountId){$account=stripeCall('POST','accounts',['type'=>'express','country'=>$country,'capabilities[card_payments][requested]'=>'true','capabilities[transfers][requested]'=>'true','metadata[goodfind_user_id]'=>(string)$user['id']]);$accountId=$account['id'];runSql('UPDATE users SET stripe_account_id=? WHERE id=?',[$accountId,(int)$user['id']]);}
        $base=rtrim(setting('APP_URL','http://localhost/goodfind'),'/');$link=stripeCall('POST','account_links',['account'=>$accountId,'refresh_url'=>$base.'/marketplace.php?payout_setup=refresh','return_url'=>$base.'/marketplace.php?payout_setup=return','type'=>'account_onboarding']);answer(200,['url'=>$link['url']]);
